type TDeleteParams = {
  responseId: string;
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
  auditLog?: TV3AuditLog;
};

/** The keys of a stored JSON map, or none when the column holds something else. */
const fieldNamesOf = (value: unknown): string[] =>
  typeof value === "object" && value !== null && !Array.isArray(value)
    ? Object.keys(value).sort((a, b) => a.localeCompare(b))
    : [];

/**
 * The deleted row as the audit trail keeps it: which response, whose, and how much it held — never what
 * it held. `redactPII` reduces content containers the same way at the sink, but the operation states
 * the shape itself so the RFC's "field names, not values" rule for response mutations does not rest on
 * a list of key names in another module. `singleUseId` and `ttc` are left out: one is a spent token, the
 * other timing telemetry, and neither helps a reviewer.
 */
const toDeletedResponseAuditRecord = (row: TDeletedResponse) => {
  const answerFieldNames = fieldNamesOf(row.data);
  const variableFieldNames = fieldNamesOf(row.variables);

  return {
    id: row.id,
    surveyId: row.surveyId,
    contactId: row.contactId,
    displayId: row.displayId,
    endingId: row.endingId,
    language: row.language,
    finished: row.finished,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
    answerFieldNames,
    answerCount: answerFieldNames.length,
    variableFieldNames,
    variableCount: variableFieldNames.length,
  };
};

/**
 * `DELETE /api/v3/responses/{responseId}` → 204.
 *
 * Returns a `Response` and never throws, because these operations have two callers: the HTTP wrapper,
 * and the MCP server, which calls them directly with no wrapper to catch anything.
 *
 * Permission is `manage`, not `write`. The shipped AuthZed schema assigns `write` to "web-session
 * mutations such as tagging or deleting" and `manage` to "delete through the legacy management APIs", so
 * the API deletes at `manage` — matching v1/v2 and the `deleteV3FeedbackRecord` precedent. The dashboard
 * keeps deleting at `write`; that divergence is deliberate until the Internal API RFC's Wave 3.
 */
export async function deleteV3Response({
  responseId,
  authentication,
  requestId,
  instance,
  auditLog,
}: TDeleteParams): Promise<Response> {
  const log = logger.withContext({ requestId, responseId });

  try {
    const workspaceId = await getResponseWorkspaceId(responseId);

    // A response that does not exist and one in another workspace answer identically. The default detail
    // is what `problemForbidden` and every pre-flight rejection use, so the bodies are byte-identical —
    // asserted as body equality in the tests, because two 403s differing by a word are still an oracle.
    if (!workspaceId) {
      return problemForbidden(requestId, undefined, instance);
    }

    const access = await requireV3WorkspaceAccess(authentication, workspaceId, "manage", requestId, instance);

    if (access instanceof Response) {
      return access;
    }

    const refused = await refuseUnlessV3SurveyVisible(
      authentication,
      "response.manage",
      { type: "response", id: responseId },
      requestId,
      instance
    );
    if (refused) return refused;

    const deleted = await deleteScopedResponse(responseId, { workspaceId });

    if (auditLog) {
      auditLog.targetId = responseId;
      auditLog.organizationId = access.organizationId;
      // What was destroyed, as identity and shape — never the answers. The row is gone, so this is the
      // only record left, and a delete that says nothing about *what* it destroyed is not reviewable.
      // But the audit store has its own retention, access model and export path, and respondent free
      // text does not belong in it (ENG-2873): field names and counts answer the reviewer's question —
      // which response, whose, how much — without carrying a single value.
      auditLog.oldObject = toDeletedResponseAuditRecord(deleted);
    }

    return noContentResponse({ requestId });
  } catch (error) {
    // The service already turned P2025 into `ResourceNotFoundError`, which this renders as the same 403
    // as the pre-flight rejection above — so a response deleted between the scope lookup and the delete
    // is indistinguishable from one that was never the caller's.
    return mapV3ThrownError(error, {
      log,
      requestId,
      instance: instance ?? "",
      operation: "responses.delete",
    });
  }
}

type TBatchDeleteParams = {
  workspaceId: string;
  ids: string[];
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
  auditLog?: TV3AuditLog;
};

/**
 * `POST /api/v3/responses/batch-delete` → 200 `{ data: { deleted } }`.
 *
 * Unlike the single delete, the scope is supplied rather than derived — a batch has no one response to
 * resolve it from, and scope-filtering is only meaningful against a known workspace. That is safe here
 * because the value authorized against and the value filtered by are the same `workspaceId`: they
 * cannot diverge, so a foreign id matches nothing instead of being deleted under a scope the caller
 * does hold. Deriving it from the ids instead would mean authorizing every distinct workspace the batch
 * touches, which contradicts the contract's promise to ignore out-of-scope ids rather than refuse them.
 *
 * A shortfall is not an error: `deleted` is allowed to be lower than `ids.length`, or zero.
 */
export async function batchDeleteV3Responses({
  workspaceId,
  ids,
  authentication,
  requestId,
  instance,
  auditLog,
}: TBatchDeleteParams): Promise<Response> {
  const log = logger.withContext({ requestId, workspaceId });

  try {
    const access = await requireV3WorkspaceAccess(authentication, workspaceId, "manage", requestId, instance);

    if (access instanceof Response) {
      return access;
    }

    // ENG-3282: responses of a survey this caller cannot see are scope-filtered out like foreign ids —
    // simply not counted in `deleted` — rather than refused (contract §7).
    const visibleSurveyWhere = buildVisibleSurveyWhere(
      await resolveV3ResponsesActorContext(authentication, access.organizationId)
    );
    const { deleted, deletedIds } = await deleteScopedResponses(ids, { visibleSurveyWhere, workspaceId });

    if (auditLog) {
      auditLog.organizationId = access.organizationId;
      // Identity only, deliberately. The single delete records the whole row because there is exactly
      // one; a batch of up to 100 would put an unbounded blob in a log line, and the ids are what makes
      // the action reviewable. `requested` is kept alongside `deleted` so a shortfall is legible after
      // the fact rather than looking like a partial failure.
      auditLog.oldObject = { workspaceId, requested: ids.length, deleted, responseIds: deletedIds };
    }

    log.info({ requested: ids.length, deleted }, "V3 responses batch deleted");

    return successResponse({ deleted }, { requestId });
  } catch (error) {
    return mapV3ThrownError(error, {
      log,
      requestId,
      instance: instance ?? "",
      operation: "responses.batchDelete",
    });
  }
}

type TReadParams = {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
};

/** How many rejected parameter names one log line will carry; the rest are counted, not named. */
const MAX_LOGGED_REJECTED_PARAMS = 10;

/**
 * A rejected name is only logged when it looks like a query key — the bracket-and-dot vocabulary the
 * contract uses, bounded in length. Anything else is caller-supplied text and is counted instead.
 */
const LOGGABLE_PARAM_NAME = /^[\w[\].-]{1,64}$/;

/**
 * Turn a parse failure into the 400 the contract promises.
 *
 * The parser reports every offending key at once, so a caller fixing a query sees all of it rather
 * than one problem per round trip.
 *
 * The rejected parameter *names* are logged, because they are the other half of ENG-2898 §1: a
 * caller sending `filter[tags]` is refused, and the refusal is the only evidence that anyone wants
 * tag filtering (ENG-2897). Names only, never values — and the names are caller-controlled, so the
 * line is bounded twice over: only key-shaped names of bounded length, and at most a handful of
 * them, with the total alongside so a flood is still visible as a number.
 */
const badQuery = (
  invalidParams: TV3InvalidParam[],
  requestId: string,
  instance: string | undefined,
  log: ReturnType<typeof logger.withContext>
): Response => {
  log.info(
    {
      rejectedParamCount: invalidParams.length,
      rejectedParams: invalidParams
        .map((param) => param.name)
        .filter((name) => LOGGABLE_PARAM_NAME.test(name))
        .slice(0, MAX_LOGGED_REJECTED_PARAMS),
    },
    "v3 responses query rejected"
  );

  return problemBadRequest(requestId, "The query parameters are invalid.", {
    invalid_params: invalidParams,
    instance,
  });
};

/**
 * `GET /api/v3/responses` → 200 `{ data, meta }`.
 *
 * Authorization comes before the cursor is even looked at: the scope is the caller's `workspaceId`,
 * checked against `read`, and everything below runs inside it. That ordering is what lets the cursor
 * carry no authority of its own — it is a position, re-authorized on every request.
 *
 * `meta` always carries all four keys. `totalCount` and `totalCountRelation` are `null` rather than
 * absent when the caller did not ask for a total, because the contract marks them required — a caller
 * can branch on the value without first checking the key exists.
 */
export async function listV3Responses({
  searchParams,
  authentication,
  requestId,
  instance,
}: TReadParams & { searchParams: URLSearchParams }): Promise<Response> {
  const log = logger.withContext({ requestId });
  const read = startV3ResponsesRead({ operation: "list", authentication, instance });

  try {
    const parsed = parseV3ResponsesListQuery(searchParams);
    if (!parsed.ok) {
      return read.done(badQuery(parsed.invalid_params, requestId, instance, log));
    }

    read.observation.filter = parsed.filter;
    read.observation.cursorUsed = parsed.cursor !== null;
    read.observation.includeTotalCount = parsed.includeTotalCount;

    const access = await requireV3WorkspaceAccess(
      authentication,
      parsed.filter.workspaceId,
      "read",
      requestId,
      instance
    );

    if (access instanceof Response) {
      return read.done(access);
    }

    // ENG-3282: a named survey the caller cannot read answers the same 403 as an unknown one; without
    // one, its responses are simply absent from the page and the total (contract §7).
    const surveyRefused = parsed.filter.surveyId
      ? await refuseUnlessV3SurveyVisible(
          authentication,
          "survey.response_read",
          { type: "survey", id: parsed.filter.surveyId },
          requestId,
          instance
        )
      : null;
    if (surveyRefused) return read.done(surveyRefused);
    const actorContext = await resolveV3ResponsesActorContext(authentication, access.organizationId);

    const keysetRows = await listV3ResponseKeysetPage({
      access: actorContext,
      filter: parsed.filter,
      sortBy: parsed.sortBy,
      limit: parsed.limit,
      cursor: parsed.cursor,
    });

    const { page, nextCursor } = buildKeysetPage({
      rows: keysetRows,
      limit: parsed.limit,
      kind: RESPONSES_CURSOR_KIND,
      sortBy: parsed.sortBy,
      fp: parsed.fingerprint,
      sortValue: (row) => row.createdAt,
    });

    // Three independent queries, so all three go together: hydration, the surveys the page refers
    // to, and the total when it was asked for. The surveys are keyed off the keyset page rather
    // than the hydrated rows — phase one already carries `surveyId`, so waiting for the hydration
    // to learn which surveys to load would serialize two queries that need nothing from each other.
    const pageSurveyIds = page.map((row) => row.surveyId);
    read.observation.pageSurveyCount = new Set(pageSurveyIds).size;

    const [rows, surveys, total] = await Promise.all([
      hydrateV3Responses(page.map((row) => row.id)),
      getV3ResponseSurveys(pageSurveyIds),
      parsed.includeTotalCount
        ? countV3Responses({ access: actorContext, filter: parsed.filter, precision: "capped" })
        : Promise.resolve(null),
    ]);

    const serializer = createV3ResponseSerializer();

    // A response whose survey vanished between the two queries cannot be serialized against a
    // definition. Dropping it keeps the page valid rather than failing the whole read for one row;
    // it is logged because it should not happen outside a concurrent delete.
    const data = rows.flatMap((row) => {
      const survey = surveys.get(row.surveyId);
      if (!survey) {
        log.warn({ responseId: row.id, surveyId: row.surveyId }, "v3 list: survey missing for response");
        return [];
      }

      return [serializer.toListItem(row, survey)];
    });

    read.observation.items = data;

    return read.done(
      successListResponse(
        data,
        {
          limit: parsed.limit,
          nextCursor,
          totalCount: total?.count ?? null,
          totalCountRelation: total?.relation ?? null,
        },
        { requestId, cache: "private, no-store" }
      )
    );
  } catch (error) {
    return read.done(
      mapV3ThrownError(error, {
        log,
        requestId,
        instance: instance ?? "",
        operation: "responses.list",
      })
    );
  }
}

/**
 * `GET /api/v3/responses/count` → 200 `{ data: { count, relation } }`.
 *
 * Exists so "how many match this filter" never requires fetching a page. `precision=exact` is the
 * documented slow path; the default stops counting at the cap and says so through `relation`.
 */
export async function countV3ResponsesOperation({
  searchParams,
  authentication,
  requestId,
  instance,
}: TReadParams & { searchParams: URLSearchParams }): Promise<Response> {
  const log = logger.withContext({ requestId });
  const read = startV3ResponsesRead({ operation: "count", authentication, instance });

  try {
    const parsed = parseV3ResponsesCountQuery(searchParams);
    if (!parsed.ok) {
      return read.done(badQuery(parsed.invalid_params, requestId, instance, log));
    }

    read.observation.filter = parsed.filter;
    read.observation.precision = parsed.precision;

    const access = await requireV3WorkspaceAccess(
      authentication,
      parsed.filter.workspaceId,
      "read",
      requestId,
      instance
    );

    if (access instanceof Response) {
      return read.done(access);
    }

    const surveyRefused = parsed.filter.surveyId
      ? await refuseUnlessV3SurveyVisible(
          authentication,
          "survey.response_read",
          { type: "survey", id: parsed.filter.surveyId },
          requestId,
          instance
        )
      : null;
    if (surveyRefused) return read.done(surveyRefused);

    const { count, relation } = await countV3Responses({
      access: await resolveV3ResponsesActorContext(authentication, access.organizationId),
      filter: parsed.filter,
      precision: parsed.precision,
    });

    return read.done(successResponse({ count, relation }, { requestId, cache: "private, no-store" }));
  } catch (error) {
    return read.done(
      mapV3ThrownError(error, {
        log,
        requestId,
        instance: instance ?? "",
        operation: "responses.count",
      })
    );
  }
}

/**
 * `GET /api/v3/responses/{responseId}` → 200 `{ data }`.
 *
 * The workspace is resolved from the response rather than supplied, so a caller cannot pair someone
 * else's response id with a workspace it happens to have access to. A response that does not exist
 * and one in another workspace answer with the same 403 and the same default detail — 404 would make
 * the id space probeable.
 */
export async function getV3Response({
  responseId,
  authentication,
  requestId,
  instance,
}: TReadParams & { responseId: string }): Promise<Response> {
  const log = logger.withContext({ requestId, responseId });
  const read = startV3ResponsesRead({ operation: "get", authentication, instance });

  try {
    const workspaceId = await getResponseWorkspaceId(responseId);

    if (!workspaceId) {
      return read.done(problemForbidden(requestId, undefined, instance));
    }

    const access = await requireV3WorkspaceAccess(authentication, workspaceId, "read", requestId, instance);

    if (access instanceof Response) {
      return read.done(access);
    }

    const refused = await refuseUnlessV3SurveyVisible(
      authentication,
      "response.read",
      { type: "response", id: responseId },
      requestId,
      instance
    );
    if (refused) return read.done(refused);

    const row = await getScopedV3Response(responseId, { workspaceId });

    // Deleted between the scope lookup and the read. The same 403 as above, so the race is
    // indistinguishable from a response that was never the caller's.
    if (!row) {
      return read.done(problemForbidden(requestId, undefined, instance));
    }

    const surveys = await getV3ResponseSurveys([row.surveyId]);
    const survey = surveys.get(row.surveyId);

    if (!survey) {
      return read.done(problemForbidden(requestId, undefined, instance));
    }

    const resource = createV3ResponseSerializer().toResource(row, survey);
    read.observation.items = [resource];

    return read.done(successResponse(resource, { requestId, cache: "private, no-store" }));
  } catch (error) {
    return read.done(
      mapV3ThrownError(error, {
        log,
        requestId,
        instance: instance ?? "",
        operation: "responses.get",
      })
    );
  }
}

/**
 * Compose one write's two stored maps, or the reasons it cannot be composed.
 *
 * Shared by create and patch because the rules are identical — what differs is only which keys the
 * payload carried and whether there is a stored row underneath. Every issue it returns is a 422:
 * each one needed the survey definition to detect, which is precisely the line the contract draws
 * between 400 and 422 on these operations.
 */
function composeV3ResponseWrite({
  plan,
  survey,
  body,
  stored,
}: {
  plan: ReturnType<typeof buildAnswerPlan>;
  survey: TV3WriteSurveyRow;
  body: { data?: TResponseData; embeddedData?: Record<string, string | number | boolean | null> };
  stored: { data: TResponseData; variables: Record<string, TResponseDataValue> } | undefined;
}): {
  issues: InvalidParam[];
  data: TResponseData | undefined;
  variables: Record<string, TResponseDataValue> | undefined;
} {
  const issues: InvalidParam[] = [];

  let data = stored?.data;
  let dataTouched = false;

  if (body.data !== undefined) {
    const answerPlan = planAnswerDataWrite(plan, body.data, stored?.data);
    issues.push(...answerPlan.issues);
    data = answerPlan.data;
    dataTouched = true;
  }

  let variables = stored?.variables;
  let variablesTouched = false;

  if (body.embeddedData !== undefined) {
    const embeddedPlan = planEmbeddedDataWrite({
      embeddedFields: survey.embeddedFields ?? [],
      elementIds: new Set(plan.elementById.keys()),
      incoming: body.embeddedData,
    });
    issues.push(...embeddedPlan.issues);

    // Applied over whatever the answer step produced, which is what makes `embeddedData` a merge
    // while `data` is a replacement: a field the payload omits keeps the value already in the map.
    const nextData: TResponseData = { ...data, ...embeddedPlan.dataWrites };
    for (const key of embeddedPlan.dataClears) delete nextData[key];
    data = nextData;
    dataTouched =
      dataTouched || embeddedPlan.dataClears.length > 0 || Object.keys(embeddedPlan.dataWrites).length > 0;

    const nextVariables = { ...variables, ...embeddedPlan.variableWrites };
    for (const key of embeddedPlan.variableClears) delete nextVariables[key];
    variables = nextVariables;
    variablesTouched =
      embeddedPlan.variableClears.length > 0 || Object.keys(embeddedPlan.variableWrites).length > 0;
  }

  return {
    issues,
    data: dataTouched ? (data ?? {}) : undefined,
    variables: variablesTouched ? (variables ?? {}) : undefined,
  };
}

/**
 * File-upload answers must point at files this workspace, survey and element own.
 *
 * Every v1 and v2 write path runs this, and omitting it is not a cosmetic gap: a stored answer is a
 * storage path that later gets resolved into a signed URL by the dashboard, the export and the read
 * endpoints. A caller with write access to workspace A could otherwise store
 * `/storage/{workspaceB}/private/surveys/…` under a file-upload element and have it resolved on
 * their own response — the cross-tenant storage reference ENG-1981 closed on the management routes.
 *
 * `legacyOwnedStoragePrefixes` is passed for the same reason the management routes pass it: this is a
 * management-plane API, and a caller replaying an old response carries file URLs that predate the
 * scoped shape. The client widget path stays strict without it.
 *
 * 422 rather than v1/v2's 400, because the check needs the survey definition — the line this
 * contract draws between the two.
 */
async function fileUploadIssues(
  survey: TV3WriteSurveyRow,
  data: TResponseData | undefined
): Promise<InvalidParam[]> {
  if (!data) return [];

  const valid = validateClientFileUploads({
    data,
    workspaceId: survey.workspaceId,
    surveyId: survey.id,
    blocks: survey.blocks as never,
    questions: survey.questions as never,
    legacyOwnedStoragePrefixes: await getWorkspaceLegacyStoragePrefixes(survey.workspaceId),
  });

  if (valid) return [];

  return [
    {
      name: "data",
      reason: "A file-upload answer references a file that does not belong to this survey's upload element.",
      code: "invalid_reference",
      referenceType: "element",
    },
  ];
}

/** Survey validation-rule failures, itemized per element rather than collapsed into one message. */
function answerValidationIssues(
  survey: TV3WriteSurveyRow,
  data: TResponseData | undefined,
  language: string | null
) {
  const errorMap = validateResponseData(
    survey.blocks as unknown[],
    data,
    language ?? "en",
    survey.questions as never
  );

  if (!errorMap) return [];

  return Object.entries(errorMap).flatMap(([elementId, errors]) =>
    errors.map((error) => ({
      name: elementId,
      reason: error.message,
      referenceType: "element" as const,
      identifier: error.ruleId,
    }))
  );
}

type TWriteParams = {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
  auditLog?: TV3AuditLog;
};

export type TV3CreatePlan =
  | { ok: true; composed: ReturnType<typeof composeV3ResponseWrite>; storedLanguage: string | null }
  | { ok: false; issues: InvalidParam[] };

/**
 * Everything a create decides before the transaction opens: the language the response will carry,
 * the two stored maps it will write, and every reason it cannot proceed.
 *
 * Separated from the operation so `POST` and `POST /validate` cannot drift — a dry run that ran its
 * own copy of this would be worth less than nothing, since a caller would be told a payload is
 * acceptable by code that is not the code accepting it. It reads the database (file ownership) but
 * writes nothing, which is what lets the validate path stop here.
 *
 * The language is resolved first because it decides which labels the answers are validated against,
 * and it is the survey's own code rather than the caller's.
 */
export async function planV3ResponseCreate({
  survey,
  body,
}: {
  survey: TV3WriteSurveyRow;
  body: TV3CreateResponseBody;
}): Promise<TV3CreatePlan> {
  const language = resolveV3WriteLanguage(survey.languages, body.language);
  const storedLanguage = language.ok ? language.code : null;
  const { lookupKey } = resolveV3LabelContext(survey.languages, storedLanguage);
  const plan = buildAnswerPlan(
    survey.blocks as never,
    lookupKey,
    (survey.embeddedFields ?? [])
      .filter(({ field }) => field.source === "ingested")
      .map(({ link }) => link.storageKey)
  );

  const composed = composeV3ResponseWrite({ plan, survey, body, stored: undefined });
  const issues: InvalidParam[] = [
    ...composed.issues,
    ...(language.ok ? [] : [language.issue]),
    ...[validateV3EndingId(survey.endings, body.endingId)].filter(
      (issue): issue is InvalidParam => issue !== null
    ),
    ...answerValidationIssues(survey, composed.data, storedLanguage),
    ...(await fileUploadIssues(survey, composed.data)),
  ];

  if (issues.length > 0) return { ok: false, issues };

  return { ok: true, composed, storedLanguage };
}

/**
 * `POST /api/v3/responses` → 201 `{ data }` with a `Location` header.
 *
 * **The workspace is resolved from `surveyId`, and a survey the caller cannot write to answers 403
 * whether it is missing or someone else's.** The contract's 422 list named an unresolvable
 * `surveyId` alongside `endingId`, `contactId` and the rest, but it does not belong with them: those
 * are checked *after* authorization, inside a workspace the caller already holds, so they disclose
 * nothing. `surveyId` is the scope anchor and is necessarily checked *before* it — a distinct answer
 * for "no such survey" would let any valid key probe the id space of every other tenant. The spec
 * has been corrected to match; see `api_v3_responses.yml`.
 */
export async function createV3Response({
  body,
  authentication,
  requestId,
  instance,
  auditLog,
}: TWriteParams & { body: TV3CreateResponseBody }): Promise<Response> {
  const log = logger.withContext({ requestId, surveyId: body.surveyId });

  try {
    const survey = await getSurveyForV3Write(body.surveyId);

    if (!survey) {
      return problemForbidden(requestId, undefined, instance);
    }

    const access = await requireV3WorkspaceAccess(
      authentication,
      survey.workspaceId,
      "readWrite",
      requestId,
      instance
    );

    if (access instanceof Response) {
      return access;
    }

    const refused = await refuseUnlessV3SurveyVisible(
      authentication,
      "survey.write",
      { type: "survey", id: survey.id },
      requestId,
      instance
    );
    if (refused) return refused;

    const plan = await planV3ResponseCreate({ survey, body });

    if (!plan.ok) {
      return problemUnprocessableContent(requestId, "The response conflicts with the survey definition", {
        invalid_params: plan.issues,
        instance,
      });
    }

    const { composed, storedLanguage } = plan;

    const outcome = await createScopedResponse({
      workspaceId: survey.workspaceId,
      survey,
      finished: body.finished,
      data: composed.data ?? {},
      variables: composed.variables ?? {},
      ttc: normalizeV3Ttc(body.ttc, body.finished),
      meta: body.meta,
      tagIds: body.tags ?? [],
      endingId: body.endingId,
      language: storedLanguage,
      contactId: body.contactId,
      displayId: body.displayId,
      singleUseId: body.singleUseId,
    });

    if (!outcome.ok) {
      return problemUnprocessableContent(requestId, "The response conflicts with stored data", {
        invalid_params: outcome.issues,
        instance,
      });
    }

    const row = await readbackV3Response(outcome.responseId, { workspaceId: survey.workspaceId });

    if (!row) {
      // Deleted between the commit and the read back. Nothing truthful is left to return, and the
      // row genuinely existed, so this is a server-side race rather than a caller error.
      return mapV3ThrownError(new Error("Created response disappeared before read-back"), {
        log,
        requestId,
        instance: instance ?? "",
        operation: "responses.create",
      });
    }

    if (auditLog) {
      auditLog.targetId = row.id;
      auditLog.organizationId = access.organizationId;
      auditLog.newObject = { id: row.id, surveyId: row.surveyId, finished: row.finished };
    }

    const resource = createV3ResponseSerializer().toResource(row, survey);

    // After the commit, and never fatal — see `dispatchV3ResponsePipeline`. `finished` comes from the
    // persisted row because quota evaluation can finish a response submitted as partial.
    await dispatchV3ResponsePipeline({
      event: "responseCreated",
      workspaceId: survey.workspaceId,
      surveyId: survey.id,
      response: row,
      alsoFinished: row.finished,
    });

    return createdResponse(resource, {
      location: `/api/v3/responses/${row.id}`,
      requestId,
      cache: "private, no-store",
    });
  } catch (error) {
    return mapV3ThrownError(error, {
      log,
      requestId,
      instance: instance ?? "",
      operation: "responses.create",
    });
  }
}

export type TV3PatchPlan =
  | { ok: true; composed: ReturnType<typeof composeV3ResponseWrite>; effectiveLanguage: string | null }
  | { ok: false; issues: InvalidParam[] };

/**
 * Everything a patch decides before the transaction opens: the language the response will carry, the
 * two stored maps it will write, and every reason it cannot proceed.
 *
 * The language is resolved first because it decides which labels the answers are validated against —
 * a payload that changes language and answers in one call must be checked against the labels it is
 * about to have, not the ones it is leaving behind.
 */
export async function planV3ResponsePatch({
  survey,
  body,
  stored,
}: {
  survey: TV3WriteSurveyRow;
  body: TV3PatchResponseBody;
  stored: { language: string | null; data: unknown; variables: unknown };
}): Promise<TV3PatchPlan> {
  const patchLanguage =
    body.language === undefined
      ? { ok: true as const, code: stored.language }
      : resolveV3WriteLanguage(survey.languages, body.language);
  const effectiveLanguage = patchLanguage.ok ? patchLanguage.code : null;
  const { lookupKey } = resolveV3LabelContext(survey.languages, effectiveLanguage);

  const plan = buildAnswerPlan(
    survey.blocks as never,
    lookupKey,
    (survey.embeddedFields ?? [])
      .filter(({ field }) => field.source === "ingested")
      .map(({ link }) => link.storageKey)
  );

  const composed = composeV3ResponseWrite({
    plan,
    survey,
    body,
    stored: {
      data: (stored.data ?? {}) as TResponseData,
      variables: (stored.variables ?? {}) as Record<string, TResponseDataValue>,
    },
  });

  const endingIssue = body.endingId === undefined ? null : validateV3EndingId(survey.endings, body.endingId);

  const issues: InvalidParam[] = [
    ...composed.issues,
    ...(patchLanguage.ok ? [] : [patchLanguage.issue]),
    ...(endingIssue ? [endingIssue] : []),
    // Only what the caller supplied — see `answerValidationIssues`.
    ...(body.data === undefined ? [] : answerValidationIssues(survey, composed.data, effectiveLanguage)),
    // Gated on `body.data` for the same reason as the line above. `composed.data` is the merged map,
    // so an `embeddedData`-only patch would otherwise re-run stored upload URLs through today's
    // `allowedFileExtensions`: narrow those after collection and every later patch 422s naming `data`,
    // a field the request never carried.
    ...(body.data === undefined ? [] : await fileUploadIssues(survey, composed.data)),
  ];

  if (issues.length > 0) return { ok: false, issues };

  return { ok: true, composed, effectiveLanguage };
}

/**
 * `PATCH /api/v3/responses/{responseId}` → 200 `{ data }`.
 *
 * `responseFinished` fires on the **transition** to finished, not on every patch of a response that
 * is already finished. v1 and v2 both re-emit, and this deliberately does not: the contract defines
 * the event as firing "for a patch that transitions the response to finished"
 * (`ResponseValidationEffects.firesPipeline`), and re-emitting means a correction to a typo in a
 * finished response re-runs every webhook, integration and follow-up email the original submission
 * ran. Worth knowing when comparing against the older paths.
 */
export async function updateV3Response({
  responseId,
  body,
  authentication,
  requestId,
  instance,
  auditLog,
}: TWriteParams & { responseId: string; body: TV3PatchResponseBody }): Promise<Response> {
  const log = logger.withContext({ requestId, responseId });

  try {
    const workspaceId = await getResponseWorkspaceId(responseId);

    if (!workspaceId) {
      return problemForbidden(requestId, undefined, instance);
    }

    const access = await requireV3WorkspaceAccess(
      authentication,
      workspaceId,
      "readWrite",
      requestId,
      instance
    );

    if (access instanceof Response) {
      return access;
    }

    const refused = await refuseUnlessV3SurveyVisible(
      authentication,
      "response.write",
      { type: "response", id: responseId },
      requestId,
      instance
    );
    if (refused) return refused;

    const stored = await getScopedV3Response(responseId, { workspaceId });

    if (!stored) {
      return problemForbidden(requestId, undefined, instance);
    }

    const survey = await getSurveyForV3Write(stored.surveyId);

    if (!survey) {
      return problemForbidden(requestId, undefined, instance);
    }

    const planned = await planV3ResponsePatch({ survey, body, stored });

    if (!planned.ok) {
      return problemUnprocessableContent(requestId, "The response conflicts with the survey definition", {
        invalid_params: planned.issues,
        instance,
      });
    }

    const { composed, effectiveLanguage } = planned;

    const outcome = await updateScopedResponse({
      responseId,
      workspaceId,
      survey,
      patch: {
        finished: body.finished,
        // `_total` is derived, not caller-supplied, and the shared update service computes it on any
        // write that finishes a response. Without it a response created partial and finished here
        // carries per-element timings but reports no duration at all.
        ...(body.finished === true && !stored.finished
          ? { ttc: totalStoredV3Ttc(stored.ttc as Record<string, unknown> | undefined) }
          : {}),
        endingId: body.endingId,
        // Only when the payload carried it — and then as the survey's own code, never the caller's.
        language: body.language === undefined ? undefined : effectiveLanguage,
        data: composed.data,
        variables: composed.variables,
        tagIds: body.tags,
      },
    });

    if (!outcome.ok) {
      return problemUnprocessableContent(requestId, "The response conflicts with stored data", {
        invalid_params: outcome.issues,
        instance,
      });
    }

    const row = await readbackV3Response(responseId, { workspaceId });

    if (!row) {
      return problemForbidden(requestId, undefined, instance);
    }

    if (auditLog) {
      auditLog.targetId = responseId;
      auditLog.organizationId = access.organizationId;
      auditLog.oldObject = { id: stored.id, finished: stored.finished };
      auditLog.newObject = { id: row.id, finished: row.finished };
    }

    const resource = createV3ResponseSerializer().toResource(row, survey);

    await dispatchV3ResponsePipeline({
      event: "responseUpdated",
      workspaceId,
      surveyId: survey.id,
      response: row,
      // The transition, not the state — see the note on this function.
      alsoFinished: !stored.finished && row.finished,
    });

    return successResponse(resource, { requestId, cache: "private, no-store" });
  } catch (error) {
    return mapV3ThrownError(error, {
      log,
      requestId,
      instance: instance ?? "",
      operation: "responses.update",
    });
  }
}

/**
 * `createV3Response` and `updateV3Response` for a caller that holds an unparsed body.
 *
 * The route never needs these — `withV3ApiWrapper` parses the body against the same schemas before
 * the handler runs, and answers the 400 itself. The MCP tools do: they receive whatever the model
 * produced, and the schema failure has to become a tool result rather than a thrown error. Without
 * them each tool would parse for itself, which is how two callers of one operation end up disagreeing
 * about what a malformed body earns.
 */
export async function createV3ResponseFromRawInput({
  body,
  ...params
}: TWriteParams & { body: unknown }): Promise<Response> {
  const parsed = ZV3CreateResponseBody.safeParse(body);

  if (!parsed.success) {
    return problemBadRequest(params.requestId, "Invalid request body", {
      invalid_params: formatZodIssues(parsed.error, "body"),
      instance: params.instance,
    });
  }

  return await createV3Response({ body: parsed.data, ...params });
}

export async function updateV3ResponseFromRawInput({
  responseId,
  body,
  ...params
}: TWriteParams & { responseId: string; body: unknown }): Promise<Response> {
  const parsed = ZV3PatchResponseBody.safeParse(body);

  if (!parsed.success) {
    return problemBadRequest(params.requestId, "Invalid request body", {
      invalid_params: formatZodIssues(parsed.error, "body"),
      instance: params.instance,
    });
  }

  return await updateV3Response({ responseId, body: parsed.data, ...params });
}

import { z } from "zod";
import {
  zBatchDeleteResponsesRequest,
  zBatchDeleteResponsesV3Query,
  zCreateResponseRequest,
  zGetResponseV3Path,
  zPatchResponseRequest,
  zResponseDataMapInput,
  zResponseEmbeddedDataInput,
  zResponseTtcMap,
  zValidateResponseCreateRequest,
  zValidateResponsePatchRequest,
} from "@formbricks/api-v3-schemas";
import { declareReference } from "./reference-manifest";

/**
 * The request schemas of the v3 response routes.
 *
 * The shapes are generated from the contract (`@formbricks/api-v3-schemas`); this module adds what a
 * generated schema cannot carry, and nothing else:
 *
 * - the constraints the generator cannot express — `uniqueItems`, `minProperties`/`maxProperties`
 *   and the `if/then` value caps. Each one is pinned in the package's `EXPECTED_UNENFORCED`, and
 *   `write-schemas.test.ts` rejects a counterexample for every pin, so a constraint published on the
 *   contract cannot go unenforced here.
 * - the messages a caller reads in `invalid_params[].reason`.
 * - strictness for parameter objects, which the generator emits stripping because OpenAPI has no way to
 *   close a parameter list.
 * - the reference declarations of ENG-2861, which must sit on the exact instances the bodies expose.
 *
 * Compose first, refine last: Zod 4 refuses `.extend` over a key once a schema has refinements, and a
 * `.refine` clones its schema — so each declaration below targets the instance that ends up in the
 * final shape.
 */

/** `uniqueItems`, as a refinement. Shared with MCP tools that call the operations directly. */
export const hasUniqueItems = (values: readonly unknown[]): boolean => new Set(values).size === values.length;
export const RESPONSE_IDS_UNIQUE_MESSAGE = "Response ids must be unique";

/**
 * The response id is a path parameter, so it is validated here rather than trusted: an unparseable id
 * must answer 400 before any query runs, not 500 from Prisma (ENG-483 is that bug on the v1 route).
 * `GET`, `PATCH` and `DELETE` share the one `ResponseIdPath` parameter, so any of their path schemas
 * serves.
 */
export const ZV3ResponseIdParams = z.strictObject(zGetResponseV3Path.shape);
export type TV3ResponseIdParams = z.infer<typeof ZV3ResponseIdParams>;

/**
 * `POST /api/v3/responses/batch-delete`.
 *
 * The cap and the uniqueness rule are the contract's, and both are enforced here rather than left to
 * the service: an oversized batch must answer 400 before it reaches a `deleteMany`, and duplicates
 * would make `deleted` unreconcilable against `ids.length` for no benefit to the caller. The rule sits
 * on the array, not the body, so it still reports when another field of the body is also wrong.
 */
export const ZV3BatchDeleteResponsesQuery = z.strictObject(zBatchDeleteResponsesV3Query.shape);
export type TV3BatchDeleteResponsesQuery = z.infer<typeof ZV3BatchDeleteResponsesQuery>;

export const ZV3BatchDeleteResponsesBody = zBatchDeleteResponsesRequest.extend({
  ids: zBatchDeleteResponsesRequest.shape.ids.refine(hasUniqueItems, {
    message: RESPONSE_IDS_UNIQUE_MESSAGE,
  }),
});
export type TV3BatchDeleteResponsesBody = z.infer<typeof ZV3BatchDeleteResponsesBody>;

/**
 * Cardinality caps on a stored answer, per the ENG-1652 input policy — the same reason `tags` and the
 * batch-delete body are capped.
 *
 * Both are far past any real survey: a multi-select answer holds at most one entry per choice, and a
 * response holds at most one entry per element. Without them a single request inside the 2 MB body
 * limit can store an array of tens of thousands of entries, and every later reader pays for it per
 * entry — the serializer's per-answer mapping, export columns, and the positional probe the "Other"
 * response filter emits (ENG-3161), whose window is sized from the survey's choice count rather than
 * from the stored array.
 *
 * v3-only, and additive: the same unbounded shape reaches `ZResponseData` through the v1 and v2 write
 * paths, where capping it would reject payloads that work today.
 */
export const MAX_RESPONSE_DATA_VALUES = 1_000;
export const MAX_RESPONSE_DATA_KEYS = 500;

/**
 * `ResponseDataMapInput`: the stored answer map with the write-side bounds.
 *
 * The contract caps each value with `if/then` — an array at most 1000 items, a matrix at most 1000
 * rows — and the map with `maxProperties`. The value caps refine the generated value union and the
 * key cap refines the map, which reports issues exactly as the per-value `.max()` schema did: a value
 * over its cap and a map over 500 keys are both reported, while a value of the wrong shape fails the
 * map's parse and Zod then skips the key cap. The array cap raises Zod's own `too_big` issue, so its
 * `reason` reads the way a `.max()` would.
 */
const ZV3ResponseDataValue = zResponseDataMapInput.valueType.superRefine((value, ctx) => {
  if (Array.isArray(value)) {
    if (value.length > MAX_RESPONSE_DATA_VALUES) {
      ctx.addIssue({
        code: "too_big",
        origin: "array",
        maximum: MAX_RESPONSE_DATA_VALUES,
        inclusive: true,
        input: value,
      });
    }
  } else if (typeof value === "object" && Object.keys(value).length > MAX_RESPONSE_DATA_VALUES) {
    ctx.addIssue({
      code: "custom",
      input: value,
      message: `A matrix answer may hold at most ${MAX_RESPONSE_DATA_VALUES} rows`,
    });
  }
});

const ZV3ResponseDataInput = z
  .record(zResponseDataMapInput.keyType, ZV3ResponseDataValue)
  .refine((entries) => Object.keys(entries).length <= MAX_RESPONSE_DATA_KEYS, {
    message: `A response may answer at most ${MAX_RESPONSE_DATA_KEYS} fields`,
  });

/**
 * The same key cap `data` carries, for the other two element-keyed maps on this body.
 *
 * `embeddedData` needs it for a second reason beyond storage: every name that matches no declared
 * field becomes its own `invalid_params` entry, and the entry repeats the name in both `name` and
 * `reason`. Uncapped, a 2 MB body of distinct short names answers with a 422 several times its own
 * size — the request is rejected, and the rejection is the expensive part. Only Hub-relayed
 * `invalid_params` are bounded (`hub-errors.ts`); locally generated ones are not.
 */
const withKeyCap = <T extends z.ZodType<Record<string, unknown>>>(schema: T, what: string) =>
  schema.refine((entries) => Object.keys(entries).length <= MAX_RESPONSE_DATA_KEYS, {
    message: `A response may carry at most ${MAX_RESPONSE_DATA_KEYS} ${what}`,
  });

/** Embedded Data accepts scalars only, plus `null` to clear a field — per `ResponseEmbeddedDataInput`. */
const ZV3EmbeddedDataInput = withKeyCap(zResponseEmbeddedDataInput, "Embedded Data fields");

/**
 * Per-element timing, in milliseconds. Values are not bounded on purpose — the contract clamps rather
 * than rejects, because noisy client telemetry should never cost a caller their response. The clamp
 * lives in the service.
 */
const ZV3TtcInput = withKeyCap(zResponseTtcMap, "timing entries");

const createShape = zCreateResponseRequest.shape;
const patchShape = zPatchResponseRequest.shape;

/**
 * Bounded like the batch-delete body. Without the cap one 2 MB request becomes a `WHERE id IN (…)` of
 * tens of thousands of ids plus that many join-row inserts, all inside the write transaction. Unique on
 * create only, as the contract has it: a patch applies its tags as a set, and the service deduplicates
 * them before writing the join rows.
 */
const ZV3CreateTags = createShape.tags
  .unwrap()
  .refine(hasUniqueItems, { message: "Tag ids must be unique" })
  .optional();

/**
 * Every value on a body that names something outside it, declared once (ENG-2861).
 *
 * `reference-manifest.test.ts` reads the bodies, not this list: a new field — including one a spec edit
 * adds through generation — fails there until it is classified here. The point is that the set cannot
 * grow quietly: the twelve response BOLA fixes were each a field nobody knew was a reference.
 */
const fk = (resolvedAgainst: string) => ({ kind: "fk" as const, resolvedAgainst });
const local = (resolvedAgainst: string) => ({ kind: "document-local" as const, resolvedAgainst });
const TAGS_RESOLVED = "Tag filtered by workspaceId in one query, and connected scoped in the write";

declareReference(createShape.surveyId, fk("Survey, resolved and authorized by workspace before the write"));
declareReference(
  createShape.contactId,
  fk("Contact filtered by workspaceId, and connected scoped in the write")
);
declareReference(
  createShape.displayId,
  fk("Display filtered by surveyId and unclaimed, and connected scoped in the write")
);
declareReference(ZV3CreateTags, fk(TAGS_RESOLVED));
declareReference(patchShape.tags, fk(TAGS_RESOLVED));
for (const shape of [createShape, patchShape]) {
  declareReference(shape.endingId, local("the survey's own endings"));
  declareReference(shape.language, local("the survey's own enabled languages"));
}
declareReference(
  ZV3ResponseDataInput,
  local("the survey's element ids; file-upload values additionally carry an embedded-id")
);
declareReference(ZV3EmbeddedDataInput, local("the survey's declared Embedded Data field names"));
declareReference(
  createShape.singleUseId,
  local("unused for this survey — a token, scoped by surveyId rather than owned elsewhere")
);

/**
 * `POST /api/v3/responses`.
 *
 * Three required fields and nothing implied: `surveyId`, `finished` and `data`. Everything the
 * caller may not set is absent from the shape rather than stripped afterwards, so strictness turns an
 * attempt into a 400 naming the key instead of a silent drop — which is the difference between a
 * caller learning that `createdAt` is server-owned and one believing they backdated a response.
 */
export const ZV3CreateResponseBody = zCreateResponseRequest.extend({
  data: ZV3ResponseDataInput,
  embeddedData: ZV3EmbeddedDataInput.optional(),
  ttc: ZV3TtcInput.optional(),
  tags: ZV3CreateTags,
});
export type TV3CreateResponseBody = z.infer<typeof ZV3CreateResponseBody>;

/**
 * `PATCH /api/v3/responses/{responseId}`.
 *
 * Six patchable fields, and at least one of them — an empty body is a 400 rather than a no-op 200,
 * because a caller sending nothing has a bug and a 200 would hide it.
 */
export const ZV3PatchResponseBody = zPatchResponseRequest
  .extend({
    data: ZV3ResponseDataInput.optional(),
    embeddedData: ZV3EmbeddedDataInput.optional(),
  })
  .refine((body) => Object.keys(body).length > 0, { message: "At least one field must be provided" });
export type TV3PatchResponseBody = z.infer<typeof ZV3PatchResponseBody>;

/**
 * `POST /api/v3/responses/validate`.
 *
 * A union discriminated on `operation`, each arm carrying the body the real call would take, like
 * `ZV3SurveyValidationRequestBody`. The envelope is strict and its failures are the endpoint's only
 * 400 — `data` is any value precisely because problems inside it are the point of the endpoint and come
 * back as a `200` with `valid: false`.
 *
 * `data` is required rather than merely `unknown`: Zod treats an `unknown` field as satisfiable by an
 * absent key, so without the check `{ "operation": "create" }` would validate an empty document and
 * report it as a caller error rather than as the malformed envelope it is.
 */
const ZV3ValidationDocument = declareReference(
  z.unknown().refine((value) => value !== undefined, { message: "Required" }),
  local("the nested create or patch body, whose own fields carry their declarations")
);

/**
 * The envelope's own `responseId`. A dry run resolves it exactly as a real patch does —
 * `getResponseWorkspaceId`, then the scoped read — so validate cannot be used to probe whether a
 * response exists in someone else's workspace.
 */
declareReference(
  zValidateResponsePatchRequest.shape.responseId,
  fk("Response, via getResponseWorkspaceId then the workspace-scoped read")
);

export const ZV3ResponseValidationRequestBody = z.discriminatedUnion("operation", [
  zValidateResponseCreateRequest.extend({ operation: z.literal("create"), data: ZV3ValidationDocument }),
  zValidateResponsePatchRequest.extend({ operation: z.literal("patch"), data: ZV3ValidationDocument }),
]);
export type TV3ResponseValidationRequestBody = z.infer<typeof ZV3ResponseValidationRequestBody>;

/**
 * V3 API response helpers — RFC 9457 Problem Details (application/problem+json)
 * and list envelope for success responses.
 */

const PROBLEM_JSON = "application/problem+json" as const;
const CACHE_NO_STORE = "private, no-store" as const;

/**
 * Authentication scheme advertised on a 401. RFC 9110 §15.5.2 requires "a WWW-Authenticate header field
 * containing at least one challenge **applicable to the target resource**" — the qualifier is the whole
 * point, so quote it in full: an inapplicable challenge does not satisfy the requirement, it just makes
 * a false statement about the endpoint.
 *
 * Bearer is applicable wherever this API accepts `Authorization: Bearer <fbk_…>`, which `api-key-auth.ts`
 * does — so on the `apiKey` and `both` auth modes, and nowhere else. RFC 6750 §3 requires at least one
 * auth-param, so the realm stays; a bare `Bearer` would be non-conformant.
 *
 * Deliberately NOT sent on `session` routes, and not by `problemUnauthorized` itself: cookies are not an
 * HTTP authentication scheme (they appear nowhere in the IANA HTTP Authentication Scheme Registry), so a
 * cookie-only endpoint has no applicable challenge and the MUST is unsatisfiable there. The repo's own
 * OpenAPI already concedes this by modelling the session as `type: apiKey, in: cookie` rather than
 * `type: http`. Omitting beats advertising a scheme the route will never honour.
 *
 * The MCP surface builds its own richer challenge (`resource_metadata` and `scope`, which its spec
 * MUSTs and its SDK parses) in `withOAuthChallenge` — see `@/modules/mcp/auth`.
 */
export const BEARER_CHALLENGE = 'Bearer realm="formbricks"' as const;

/** Attach the bearer challenge to a 401. Applied by the wrapper for the auth modes it is true of. */
export function withBearerChallenge(response: Response): Response {
  const headers = new Headers(response.headers);
  headers.set("WWW-Authenticate", BEARER_CHALLENGE);
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

/**
 * The `code` vocabulary of this API's problem responses: a stable, locale-independent discriminator that
 * clients switch on instead of parsing `detail` (see `parseV3ApiError` in `@/modules/api/lib/v3-client`
 * and `responseToMcpToolResult` in `@/modules/mcp/errors`).
 *
 * This list is the source of truth. `Problem.yml` in the OpenAPI spec publishes the same set, and
 * `problem-codes.test.ts` fails if the two drift — the spec used to be hand-maintained, with nothing
 * checking it against the emitters. Codes are additive: removing or renaming one is a breaking change
 * for every client that branches on it.
 *
 * `invalid_workflow_state` and `workflow_not_executable` are emitted only by `@formbricks/workflows`,
 * which mirrors this vocabulary rather than importing it (it is a leaf package, deliberately
 * dependency-free) and also emits five of the codes above; its own `WORKFLOW_PROBLEM_CODES` is held to
 * this set by a drift test on the same spec file. Named rather than counted: the array is kept sorted by
 * `problem-codes.test.ts`, so any positional claim falsifies itself on the next insertion.
 */
export const V3_PROBLEM_CODES = [
  "ai_features_not_enabled",
  "ai_generated_payload_invalid",
  "ai_instance_not_configured",
  "ai_output_too_long",
  "ai_provider_auth_failed",
  "ai_smart_tools_disabled",
  "bad_gateway",
  "bad_request",
  "chart_in_use",
  "conflict",
  "creatives_not_entitled",
  "custom_css_plan_required",
  "dashboards_plan_required",
  "forbidden",
  "internal_server_error",
  "invalid_workflow_state",
  "not_authenticated",
  "not_found",
  "payload_too_large",
  "projection_pending",
  "service_unavailable",
  "stored_survey_invalid",
  "survey_has_linked_creatives",
  "survey_not_workspace_visible",
  "too_many_requests",
  "unprocessable_content",
  "visibility_blocked_by_connections",
  "visibility_change_not_allowed",
  "visibility_not_enabled",
  "workflow_not_executable",
  "workspace_survey_limit_reached",
] as const;

export type V3ProblemCode = (typeof V3_PROBLEM_CODES)[number];

/**
 * Codes emitted only by internal routes (`app/api/internal` and the older `app/api/(internal)` group),
 * which reuse these RFC 9457 helpers but are session-only and carry no published contract.
 *
 * Kept apart from `V3_PROBLEM_CODES` rather than folded into it, because that list is held to
 * `Problem.yml` by exact equality in both directions: adding an internal code there would publish, to
 * every public client, a discriminator no public operation can ever return — which is the same defect
 * as an undocumented code, pointing the other way. `problem-codes.test.ts` asserts the two sets stay
 * disjoint and that none of these reaches the spec.
 */
export const INTERNAL_PROBLEM_CODES = [
  "attachment_export_empty",
  "attachment_export_too_large",
  "capacity_reached",
  "concurrency_limit_reached",
  "member_in_other_organizations",
  "retention_exemption_exists",
  "retention_exemption_not_active",
  "retention_export_too_large",
] as const;

export type InternalProblemCode = (typeof INTERNAL_PROBLEM_CODES)[number];

/**
 * What the shared helpers accept. A public v3 route should only ever pass a `V3ProblemCode`; the union
 * exists so an internal route can reuse the same helpers without widening the field back to `string`.
 */
export type ProblemCode = V3ProblemCode | InternalProblemCode;

const V3_PROBLEM_CODE_SET = new Set<V3ProblemCode>(V3_PROBLEM_CODES);

export function isV3ProblemCode(value: unknown): value is V3ProblemCode {
  return typeof value === "string" && V3_PROBLEM_CODE_SET.has(value as V3ProblemCode);
}

export const INVALID_PARAM_CODES = [
  "dangling_reference",
  "duplicate_identifier",
  "duplicate_locale",
  "forbidden_identifier",
  "immutable_identifier",
  "invalid_locale",
  "invalid_reference",
  "limit_exceeded",
  "misordered_reference",
  "missing_required_field",
  "missing_translation",
  "qsf_limit_exceeded",
  "qsf_not_recognized",
  "read_only_field",
  "unsupported_field",
  "unsupported_locale",
] as const;

export type InvalidParamCode = (typeof INVALID_PARAM_CODES)[number];

const INVALID_PARAM_CODE_SET = new Set<InvalidParamCode>(INVALID_PARAM_CODES);

export function isInvalidParamCode(value: unknown): value is InvalidParamCode {
  return typeof value === "string" && INVALID_PARAM_CODE_SET.has(value as InvalidParamCode);
}

export type InvalidParam = {
  name: string;
  reason: string;
  code?: InvalidParamCode;
  identifier?: string;
  referenceType?:
    | "block"
    | "element"
    | "ending"
    | "hiddenField"
    | "language"
    | "variable"
    | "variableName"
    | "recall";
  missingId?: string;
  firstUsedAt?: string;
  conflictsWith?: string;
};

export type ProblemExtension = {
  code?: ProblemCode;
  requestId: string;
  details?: Record<string, unknown>;
  invalid_params?: InvalidParam[];
};

export type ProblemBody = {
  type?: string;
  title: string;
  status: number;
  detail: string;
  instance?: string;
} & ProblemExtension;

function problemResponse(
  status: number,
  title: string,
  detail: string,
  requestId: string,
  options?: {
    type?: string;
    instance?: string;
    code?: ProblemCode;
    details?: Record<string, unknown>;
    invalid_params?: InvalidParam[];
    headers?: Record<string, string>;
  }
): Response {
  const body: ProblemBody = {
    title,
    status,
    detail,
    requestId,
    ...(options?.type && { type: options.type }),
    ...(options?.instance && { instance: options.instance }),
    ...(options?.code && { code: options.code }),
    ...(options?.details && { details: options.details }),
    ...(options?.invalid_params && { invalid_params: options.invalid_params }),
  };

  const headers: Record<string, string> = {
    "Content-Type": PROBLEM_JSON,
    "Cache-Control": CACHE_NO_STORE,
    "X-Request-Id": requestId,
    ...options?.headers,
  };

  return Response.json(body, { status, headers });
}

export function problemBadRequest(
  requestId: string,
  detail: string,
  options?: { invalid_params?: InvalidParam[]; instance?: string }
): Response {
  return problemResponse(400, "Bad Request", detail, requestId, {
    code: "bad_request",
    instance: options?.instance,
    invalid_params: options?.invalid_params,
  });
}

export function problemPayloadTooLarge(
  requestId: string,
  detail: string = "Payload Too Large",
  instance?: string
): Response {
  return problemResponse(413, "Payload Too Large", detail, requestId, {
    code: "payload_too_large",
    instance,
  });
}

export function problemUnauthorized(
  requestId: string,
  detail: string = "Not authenticated",
  instance?: string
): Response {
  return problemResponse(401, "Unauthorized", detail, requestId, {
    code: "not_authenticated",
    instance,
  });
}

export function problemForbidden(
  requestId: string,
  detail: string = "You are not authorized to access this resource",
  instance?: string
): Response {
  return problemResponse(403, "Forbidden", detail, requestId, {
    code: "forbidden",
    instance,
  });
}

/**
 * An AI capability the caller cannot use: 503 when this deployment has no AI configured at all, 403 when
 * it is configured but not enabled for the organization.
 *
 * `title` is the HTTP reason phrase for the status, not a description of the cause. RFC 9457 §4.2.1
 * requires that of a problem whose `type` is absent (and therefore `about:blank`), which is every v3
 * problem. The cause is carried by `code`, which is what clients branch on anyway — see
 * `getAiErrorMessage` in `@/modules/survey/components/template-list/lib/ai-error-messages`.
 */
export function problemAIUnavailable(
  requestId: string,
  detail: string,
  code: V3ProblemCode,
  instance?: string
): Response {
  const isNotConfigured = code === "ai_instance_not_configured";

  return problemResponse(
    isNotConfigured ? 503 : 403,
    isNotConfigured ? "Service Unavailable" : "Forbidden",
    detail,
    requestId,
    { code, instance }
  );
}

export function problemUnprocessableContent(
  requestId: string,
  detail: string,
  options?: { invalid_params?: InvalidParam[]; instance?: string; code?: ProblemCode }
): Response {
  return problemResponse(422, "Unprocessable Content", detail, requestId, {
    code: options?.code ?? "unprocessable_content",
    instance: options?.instance,
    invalid_params: options?.invalid_params,
  });
}

/**
 * ENG-2949: adding or editing custom CSS needs the Scale plan on Formbricks Cloud. Independent of the
 * resource, so it reveals nothing about it; removing CSS never answers this.
 */
export function problemCustomCssPlanRequired(requestId: string, detail: string, instance?: string): Response {
  return problemResponse(403, "Forbidden", detail, requestId, {
    code: "custom_css_plan_required",
    instance,
  });
}

/**
 * ENG-6584: charts and dashboards need the Dashboards add-on on Formbricks Cloud or a license that
 * includes it. Checked after authorization, so it reveals nothing to a caller without access, and
 * independent of any one resource.
 */
export function problemDashboardsPlanRequired(requestId: string, instance?: string): Response {
  return problemResponse(
    403,
    "Forbidden",
    "Dashboards are not enabled for this organization. They require the Dashboards add-on or an Enterprise license that includes it — an organization owner can enable them from the organization's billing or license settings.",
    requestId,
    { code: "dashboards_plan_required", instance }
  );
}

/**
 * ENG-6602: the instance's license doesn't include Creatives. In wind-down (the workspace still has
 * creatives) only reading them and taking them down stay allowed, and the detail says so; otherwise
 * every creatives operation answers this. Only ever answered after the caller's own access to the
 * workspace, so it reveals nothing about a workspace the caller can't see.
 */
export function problemCreativesNotEntitled(
  requestId: string,
  options: { windDown: boolean; instance?: string }
): Response {
  const detail = options.windDown
    ? "Creatives is not included in this instance's license: existing creatives can only be listed, read, paused, closed or deleted"
    : // Not "license": Formbricks Cloud has none, and Creatives isn't offered there.
      "Creatives is not available on this instance";

  return problemResponse(403, "Forbidden", detail, requestId, {
    code: "creatives_not_entitled",
    instance: options.instance,
  });
}

/**
 * ENG-3641: custom CSS that the processor rejected (syntax, size or complexity limits, processing
 * failure). A 422 like any other semantic document failure; `details.errors` carries the processor's
 * located errors (code, scope, appearance, line, column, reason), `invalid_params` the same as fields.
 */
export function problemCustomCssInvalid(
  requestId: string,
  options: { invalid_params: InvalidParam[]; errors: unknown[]; instance?: string }
): Response {
  return problemResponse(422, "Unprocessable Content", "Custom CSS failed validation", requestId, {
    code: "unprocessable_content",
    instance: options.instance,
    invalid_params: options.invalid_params,
    details: { errors: options.errors },
  });
}

/**
 * ENG-3282: survey visibility is not available here — the organization lacks the entitlement or the
 * deployment's readiness marker is unset (contract §5). Independent of the survey, so it reveals
 * nothing about it.
 */
export function problemVisibilityNotEnabled(requestId: string, instance?: string): Response {
  return problemResponse(
    403,
    "Forbidden",
    "Survey visibility is not enabled for this organization",
    requestId,
    {
      code: "visibility_not_enabled",
      instance,
    }
  );
}

/** ENG-3282: `restricted` refused while outbound connections depend on the survey; lists them. */
export function problemVisibilityBlocked(
  requestId: string,
  blockers: ReadonlyArray<Readonly<{ id: string; name: string; type: string }>>,
  instance?: string
): Response {
  return problemResponse(
    409,
    "Conflict",
    "Remove the connections that use this survey before restricting it",
    requestId,
    { code: "visibility_blocked_by_connections", details: { blockers }, instance }
  );
}

/**
 * A survey delete refused while non-archived creatives open the survey; lists them so the caller
 * can delete each one (pausing or closing a creative keeps its link).
 */
export function problemSurveyHasLinkedCreatives(
  requestId: string,
  creatives: ReadonlyArray<Readonly<{ id: string; name: string }>>,
  instance?: string
): Response {
  return problemResponse(
    409,
    "Conflict",
    "Delete the creatives that open this survey before deleting it",
    requestId,
    {
      code: "survey_has_linked_creatives",
      details: { creatives: creatives.map(({ id, name }) => ({ id, name })) },
      instance,
    }
  );
}

/** ENG-3282: `restricted` refused because the survey has no owner (Decision log #3). */
export function problemVisibilityChangeNotAllowed(requestId: string, instance?: string): Response {
  return problemResponse(
    422,
    "Unprocessable Content",
    "A survey without an author can't be restricted. Duplicate it to get a restricted copy you own.",
    requestId,
    { code: "visibility_change_not_allowed", instance }
  );
}

/**
 * ENG-3282: a grant was stored but the graph did not acknowledge it in-request. The survey stays
 * restricted until the outbox delivers it; retrying is safe.
 */
export function problemProjectionPending(requestId: string, instance?: string): Response {
  return problemResponse(
    503,
    "Service Unavailable",
    "The change is stored and will take effect shortly; the survey stays restricted until it does",
    requestId,
    { code: "projection_pending", headers: { "Retry-After": "5" }, instance }
  );
}

/**
 * ENG-3282: the workspace already holds `SURVEY_WORKSPACE_LIMIT` surveys. `details` carries the limit
 * and the current count so a client can say how many to archive or delete without a second call.
 */
export function problemWorkspaceSurveyLimit(
  requestId: string,
  limit: number,
  count: number,
  instance?: string
): Response {
  return problemResponse(
    422,
    "Unprocessable Content",
    "This workspace has reached its survey limit",
    requestId,
    {
      code: "workspace_survey_limit_reached",
      details: { count, limit },
      instance,
    }
  );
