export function problemConflict(
  requestId: string,
  detail: string,
  instance?: string,
  // ENG-3069: `details` carries the machine-readable half of an optimistic-concurrency failure
  // (`expectedUpdatedAt` / `currentUpdatedAt`). Without it a client can only re-read and guess,
  // and the human `detail` string is the wrong place for a value a retry has to compare.
  options?: { details?: Record<string, unknown> }
): Response {
  return problemResponse(409, "Conflict", detail, requestId, {
    code: "conflict",
    instance,
    ...(options?.details && { details: options.details }),
  });
}

export function problemBadGateway(
  requestId: string,
  detail: string,
  instance?: string,
  code: V3ProblemCode = "bad_gateway"
): Response {
  return problemResponse(502, "Bad Gateway", detail, requestId, {
    code,
    instance,
  });
}

/**
 * 503 for a capability that is not enabled on this deployment (as opposed to a transient outage, which
 * is a 502). `detail` should say what to configure — a bare "unavailable" is not actionable.
 */
export function problemServiceUnavailable(requestId: string, detail: string, instance?: string): Response {
  return problemResponse(503, "Service Unavailable", detail, requestId, {
    code: "service_unavailable",
    instance,
  });
}

/**
 * 503 for a route that is at its concurrency limit on this server (`concurrency` in
 * `withV3ApiWrapper`). Unlike `problemServiceUnavailable`, the capability is enabled and the caller
 * did nothing wrong: the same request succeeds once a slot frees up, and `Retry-After` says when to try.
 *
 * `capacity_reached` is an internal code. A public route that adopts the limit has to publish it in
 * `Problem.yml` first (`problem-codes.test.ts` keeps the two vocabularies apart).
 */
export function problemCapacityReached(
  requestId: string,
  retryAfterSeconds: number,
  instance?: string
): Response {
  return problemResponse(
    503,
    "Service Unavailable",
    `This server is busy with other requests like this one. Try again in ${retryAfterSeconds} seconds.`,
    requestId,
    { code: "capacity_reached", instance, headers: { "Retry-After": String(retryAfterSeconds) } }
  );
}

/**
 * 429 for a caller that already runs as many requests on a route as it may at once (`maxPerKey` in
 * `withV3ApiWrapper`'s `concurrency`). Its own code, not the rate limit's `too_many_requests`: the fix is
 * to wait for the caller's own request to finish, not to slow down, and a client says so.
 *
 * `concurrency_limit_reached` is an internal code, published the same way as `capacity_reached`.
 */
export function problemConcurrencyLimitReached(
  requestId: string,
  retryAfterSeconds: number,
  instance?: string
): Response {
  return problemResponse(
    429,
    "Too Many Requests",
    "You already have as many of these requests running as this route allows. Wait for one to finish.",
    requestId,
    { code: "concurrency_limit_reached", instance, headers: { "Retry-After": String(retryAfterSeconds) } }
  );
}

/**
 * 404 with resource details. Do not use for auth-sensitive or existence-sensitive resources:
 * the body includes resource_type and resource_id, which can leak existence to unauthenticated or unauthorized callers.
 * Prefer problemForbidden with a generic message for those cases.
 */
export function problemNotFound(
  requestId: string,
  resourceType: string,
  resourceId: string | null,
  instance?: string
): Response {
  return problemResponse(404, "Not Found", `${resourceType} not found`, requestId, {
    code: "not_found",
    details: { resource_type: resourceType, resource_id: resourceId },
    instance,
  });
}

export function problemInternalError(
  requestId: string,
  detail: string = "An unexpected error occurred.",
  instance?: string
): Response {
  return problemResponse(500, "Internal Server Error", detail, requestId, {
    code: "internal_server_error",
    instance,
  });
}

export function problemTooManyRequests(
  requestId: string,
  detail: string,
  retryAfter?: number,
  instance?: string
): Response {
  const headers: Record<string, string> = {};
  if (retryAfter !== undefined) {
    headers["Retry-After"] = String(retryAfter);
  }
  return problemResponse(429, "Too Many Requests", detail, requestId, {
    code: "too_many_requests",
    instance,
    headers,
  });
}

export function successListResponse<T, TMeta extends Record<string, unknown>>(
  data: T[],
  meta: TMeta,
  options?: { requestId?: string; cache?: string }
): Response {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    "Cache-Control": options?.cache ?? CACHE_NO_STORE,
  };
  if (options?.requestId) {
    headers["X-Request-Id"] = options.requestId;
  }
  return Response.json({ data, meta }, { status: 200, headers });
}

/**
 * Top-level members a success body may carry beside `data` — additive, never a replacement for it. The
 * custom CSS writes use it for `warnings` (ENG-3641), which describe the request rather than the
 * resource, so they stay out of `data` and a PATCH that round-trips `data` never sends them back.
 */
type TSuccessExtensions = { warnings?: unknown[]; meta?: Record<string, unknown> };

export function successResponse<T>(
  data: T,
  options?: { requestId?: string; cache?: string; status?: number; extensions?: TSuccessExtensions }
): Response {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    "Cache-Control": options?.cache ?? CACHE_NO_STORE,
  };

  if (options?.requestId) {
    headers["X-Request-Id"] = options.requestId;
  }

  return Response.json(
    {
      data,
      ...options?.extensions,
    },
    {
      status: options?.status ?? 200,
      headers,
    }
  );
}

export function createdResponse<T>(
  data: T,
  options: { location: string; requestId?: string; cache?: string; extensions?: TSuccessExtensions }
): Response {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    "Cache-Control": options.cache ?? CACHE_NO_STORE,
    Location: options.location,
  };

  if (options.requestId) {
    headers["X-Request-Id"] = options.requestId;
  }

  return Response.json(
    {
      data,
      ...options.extensions,
    },
    {
      status: 201,
      headers,
    }
  );
}

export function noContentResponse(options?: { requestId?: string; cache?: string }): Response {
  const headers: Record<string, string> = {
    "Cache-Control": options?.cache ?? CACHE_NO_STORE,
  };

  if (options?.requestId) {
    headers["X-Request-Id"] = options.requestId;
  }

  return new Response(null, {
    status: 204,
    headers,
  });
}

/**
 * V3 API auth — session (browser) or API key with workspace-scoped access.
 */
import { logger } from "@formbricks/logger";
import type { TAuthenticationApiKey } from "@formbricks/types/auth";
import { AuthorizationError, ResourceNotFoundError } from "@formbricks/types/errors";
import { type TAuthorizationActor, assertCan, can } from "@/lib/authorization";
import { getWorkspaceAuthorizationAction } from "@/lib/authorization/permission-action";
import type { TTeamPermission } from "@/modules/ee/teams/workspace-teams/types/team";
import { problemForbidden, problemUnauthorized } from "./response";
import type { TV3Authentication } from "./types";
import { type V3WorkspaceContext, resolveV3WorkspaceContext } from "./workspace-context";

export const getV3AuthorizationActor = (authentication: TV3Authentication): TAuthorizationActor | null => {
  if (authentication && "user" in authentication && authentication.user?.id) {
    return { type: "user", id: authentication.user.id };
  }

  if (authentication && "apiKeyId" in authentication && authentication.apiKeyId) {
    return { type: "apiKey", id: authentication.apiKeyId };
  }

  return null;
};

/** The signed-in user behind a session request, or `null` for an API key: who a write records as creator. */
export const getV3SessionUserId = (authentication: TV3Authentication): string | null =>
  authentication && "user" in authentication && authentication.user?.id ? authentication.user.id : null;

/**
 * Require session and workspace access. workspaceId is resolved via the V3 workspace-context layer.
 * Returns a Response (401 or 403) on failure, or the resolved workspace context on success so callers
 * use internal IDs (workspaceId, organizationId) without resolving again.
 * We use 403 (not 404) when the workspace is not found to avoid leaking resource existence.
 */
export async function requireSessionWorkspaceAccess(
  authentication: TV3Authentication,
  workspaceId: string,
  minPermission: TTeamPermission,
  requestId: string,
  instance?: string
): Promise<Response | V3WorkspaceContext> {
  // --- Session checks ---
  if (!authentication) {
    return problemUnauthorized(requestId, "Not authenticated", instance);
  }
  if (!("user" in authentication) || !authentication.user?.id) {
    return problemUnauthorized(requestId, "Session required", instance);
  }

  const userId = authentication.user.id;
  const log = logger.withContext({ requestId, workspaceId });

  try {
    // Resolve workspaceId → workspaceId, organizationId (single place to change when Workspace exists).
    const context = await resolveV3WorkspaceContext(workspaceId);

    await assertCan({ type: "user", id: userId }, getWorkspaceAuthorizationAction(minPermission), {
      type: "workspace",
      id: context.workspaceId,
    });

    return context;
  } catch (err) {
    if (err instanceof ResourceNotFoundError || err instanceof AuthorizationError) {
      const message = err instanceof ResourceNotFoundError ? "Workspace not found" : "Forbidden";
      log.warn({ statusCode: 403, errorCode: err.name }, message);
      return problemForbidden(requestId, "You are not authorized to access this resource", instance);
    }
    throw err;
  }
}

/** Session or API key: authorize `workspaceId` against the resolved V3 workspace context. */
export async function requireV3WorkspaceAccess(
  authentication: TV3Authentication,
  workspaceId: string,
  minPermission: TTeamPermission,
  requestId: string,
  instance?: string
): Promise<Response | V3WorkspaceContext> {
  if (!authentication) {
    return problemUnauthorized(requestId, "Not authenticated", instance);
  }

  if ("user" in authentication && authentication.user?.id) {
    return requireSessionWorkspaceAccess(authentication, workspaceId, minPermission, requestId, instance);
  }

  const keyAuth = authentication as TAuthenticationApiKey;
  if (keyAuth.apiKeyId && Array.isArray(keyAuth.workspacePermissions)) {
    const log = logger.withContext({ requestId, workspaceId, apiKeyId: keyAuth.apiKeyId });

    try {
      const context = await resolveV3WorkspaceContext(workspaceId);
      const allowed = await can(
        { type: "apiKey", id: keyAuth.apiKeyId },
        getWorkspaceAuthorizationAction(minPermission),
        { type: "workspace", id: context.workspaceId }
      );

      if (!allowed) {
        log.warn({ statusCode: 403 }, "API key not allowed for workspace");
        return problemForbidden(requestId, "You are not authorized to access this resource", instance);
      }

      return context;
    } catch (error) {
      if (error instanceof ResourceNotFoundError) {
        log.warn({ statusCode: 403, errorCode: error.name }, "Workspace not found");
        return problemForbidden(requestId, "You are not authorized to access this resource", instance);
      }

      throw error;
    }
  }

  return problemUnauthorized(requestId, "Not authenticated", instance);
}

import type {
  TContactAttributeDataType,
  TContactAttributeKey,
  TContactAttributeKeyType,
} from "@formbricks/types/contact-attribute-key";
import { parseV3ApiError } from "@/modules/api/lib/v3-client";

type TV3AttributeKeyItem = {
  id: string;
  key: string;
  name: string | null;
  description: string | null;
  type: TContactAttributeKeyType;
  dataType: TContactAttributeDataType;
  isUnique: boolean;
  createdAt: string;
  updatedAt: string;
};

export type TAttributeKeyListPage = {
  data: TContactAttributeKey[];
  meta: { limit: number; nextCursor: string | null; totalCount: number | null };
};

export const listAttributeKeys = async ({
  workspaceId,
  limit,
  cursor,
  params,
  signal,
}: {
  workspaceId: string;
  limit: number;
  cursor?: string | null;
  params: readonly [string, string][];
  signal?: AbortSignal;
}): Promise<TAttributeKeyListPage> => {
  const searchParams = new URLSearchParams({ workspaceId, limit: String(limit) });
  for (const [key, value] of params) searchParams.append(key, value);
  if (cursor) {
    searchParams.set("cursor", cursor);
  } else {
    // The match count is only needed once per filter, for the first page.
    searchParams.set("includeTotalCount", "true");
  }
  const response = await fetch(`/api/v3/contact-attribute-keys?${searchParams.toString()}`, {
    method: "GET",
    cache: "no-store",
    signal,
  });
  if (!response.ok) throw await parseV3ApiError(response);
  const body = (await response.json()) as {
    data: TV3AttributeKeyItem[];
    meta: TAttributeKeyListPage["meta"];
  };
  return {
    data: body.data.map((item) => ({
      ...item,
      workspaceId,
      createdAt: new Date(item.createdAt),
      updatedAt: new Date(item.updatedAt),
    })),
    meta: body.meta,
  };
};

"use client";

import { keepPreviousData, useQuery } from "@tanstack/react-query";
import { getOrganizationUsage } from "../lib/api-client";
import { organizationUsageKeys } from "../lib/query";
import type { TUsageRangeQuery } from "../lib/range";

const USAGE_STALE_TIME_MS = 60_000;

/**
 * The Usage page's numbers for one range. Every range change is a new key, and counts move slowly, so a
 * range seen in the last minute is served from cache without a refetch; the previous numbers stay on
 * screen while a new range loads.
 */
export const useOrganizationUsage = ({
  organizationId,
  range,
}: Readonly<{ organizationId: string; range: TUsageRangeQuery }>) =>
  useQuery({
    queryKey: organizationUsageKeys.usage(organizationId, range),
    queryFn: ({ signal }) => getOrganizationUsage({ organizationId, range, signal }),
    placeholderData: keepPreviousData,
    staleTime: USAGE_STALE_TIME_MS,
  });

"use client";

import { useMutation } from "@tanstack/react-query";
import { purgeFeedbackDataset } from "@/modules/ee/feedback-directory/lib/api-client";

/**
 * Request a purge of every feedback record in a dataset.
 *
 * There is deliberately no optimistic update and nothing to invalidate: the purge runs in the
 * background on the Hub and this screen lists datasets, not records, so there is no local state that
 * "records are gone" would be true of yet. Success here means *accepted*.
 */
export const usePurgeFeedbackDataset = () =>
  useMutation({
    mutationFn: (variables: { datasetId: string }) => purgeFeedbackDataset(variables.datasetId),
  });

