/**
 * POST /api/v3/webhooks/{webhookId}/duplicate — create a copy of an existing webhook.
 *
 * Server-only operation: resolves workspace access from the existing webhook, authorizes the caller,
 * and delegates to the service layer. Returns the new webhook as the success `data`.
 */
import { z } from "zod";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3EmptyQuery } from "@/app/api/v3/lib/schemas";
import { duplicateWebhook } from "./lib/operations";

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "created",
  targetType: "webhook",
  schemas: { params: z.object({ webhookId: z.string().cuid2() }), query: ZV3EmptyQuery },
  handler: async ({ parsedInput, authentication, auditLog, requestId, instance }) =>
    duplicateWebhook({
      webhookId: parsedInput.params.webhookId,
      authentication,
      auditLog,
      requestId,
      instance,
    }),
});

import "server-only";
import { logger } from "@formbricks/logger";
import { ResourceNotFoundError } from "@formbricks/types/errors";
import { getOrganizationIdFromWebhookId, getWorkspaceIdFromWebhookId } from "@/lib/utils/helper";
import { getWebhook } from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { createWebhook } from "@/modules/integrations/webhooks/lib/webhook";
import { createdResponse, problemNotFound } from "@/app/api/v3/lib/response";
import type { TV3Authentication, TV3AuditLog } from "@/app/api/v3/lib/types";
import { requireV3WorkspaceAccess } from "@/app/api/v3/lib/auth";
import { serializeV3Webhook } from "../../serializers";

export async function duplicateWebhook({
  webhookId,
  authentication,
  auditLog,
  requestId,
  instance,
}: {
  webhookId: string;
  authentication: TV3Authentication;
  auditLog?: TV3AuditLog;
  requestId: string;
  instance?: string;
}): Promise<Response> {
  const log = logger.withContext({ requestId, webhookId });

  const existingResult = await getWebhook(webhookId);
  if (!existingResult.ok || !existingResult.data) {
    return problemNotFound(requestId, "Webhook", webhookId, instance);
  }

  const existing = existingResult.data;
  const organizationId = await getOrganizationIdFromWebhookId(webhookId);
  const workspaceId = await getWorkspaceIdFromWebhookId(webhookId);

  const access = await requireV3WorkspaceAccess(
    authentication,
    workspaceId,
    "write",
    requestId,
    instance
  );

  if (access instanceof Response) {
    return access;
  }

  await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

  const newWebhook = await createWebhook(workspaceId, {
    name: `Copy of ${existing.name ?? ""}`,
    url: existing.url,
    source: "user" as const,
    triggers: existing.triggers,
    surveyIds: existing.surveyIds,
  });

  if (auditLog) {
    auditLog.targetId = newWebhook.id;
    auditLog.organizationId = organizationId;
    auditLog.newObject = { ...newWebhook };
  }

  const resource = serializeV3Webhook(newWebhook);

  return createdResponse(resource, {
    location: `/api/v3/webhooks/${newWebhook.id}`,
    requestId,
  });
}

import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/**
 * Client-facing webhook shape returned by v3 routes (no secret).
 */
export type TV3Webhook = {
  id: string;
  name: string | null;
  url: string;
  source: string;
  workspaceId: string;
  triggers: string[];
  surveyIds: string[];
  createdAt: string;
  updatedAt: string;
};

/**
 * Duplicate an existing webhook via the v3 API.
 *
 * Called from client components; the caller handles refresh/invalidation.
 */
export const duplicateWebhook = async (webhookId: string): Promise<TV3Webhook> => {
  const response = await fetch(`/api/v3/webhooks/${webhookId}/duplicate`, {
    method: "POST",
    cache: "no-store",
  });

  if (!response.ok) {
    throw await parseV3ApiError(response);
  }

  const body = (await response.json()) as { data: TV3Webhook };
  return body.data;
};

import type { Webhook } from "@formbricks/database/prisma-browser";

/**
 * Public v3 webhook shape. Excludes `secret` — it is only returned on create.
 */
export type TV3WebhookResource = {
  id: string;
  name: string | null;
  url: string;
  source: string;
  workspaceId: string;
  triggers: string[];
  surveyIds: string[];
  createdAt: string;
  updatedAt: string;
};

export function serializeV3Webhook(webhook: Webhook): TV3WebhookResource {
  return {
    id: webhook.id,
    name: webhook.name,
    url: webhook.url,
    source: webhook.source,
    workspaceId: webhook.workspaceId,
    triggers: webhook.triggers,
    surveyIds: webhook.surveyIds,
    createdAt: webhook.createdAt.toISOString(),
    updatedAt: webhook.updatedAt.toISOString(),
  };
}
